12	/// ## What it does
13	/// Checks for uses of `trio.sleep(0)` or `anyio.sleep(0)`.
14	///
15	/// ## Why is this bad?
16	/// `trio.sleep(0)` is equivalent to calling `trio.lowlevel.checkpoint()`.
17	/// However, the latter better conveys the intent of the code.
18	///
19	/// ## Example
20	/// ```python
21	/// import trio
22	///
23	///
24	/// async def func():
25	///     await trio.sleep(0)
26	/// ```
27	///
28	/// Use instead:
29	/// ```python
30	/// import trio
31	///
32	///
33	/// async def func():
34	///     await trio.lowlevel.checkpoint()
35	/// ```
36	/// ## Fix safety
37	/// This rule's fix is marked as unsafe if there's comments in the
38	/// `trio.sleep(0)` expression, as comments may be removed.
39	///
40	/// For example, the fix would be marked as unsafe in the following case:
41	/// ```python
42	/// import trio
43	///
44	///
45	/// async def func():
46	///     await trio.sleep(  # comment
47	///         # comment
48	///         0
49	///     )
50	/// ```
51	#[derive(ViolationMetadata)]
52	#[violation_metadata(stable_since = "0.5.0")]
53	pub(crate) struct AsyncZeroSleep {
54	    module: AsyncModule,
55	}
56	
57	impl AlwaysFixableViolation for AsyncZeroSleep {
58	    #[derive_message_formats]
59	    fn message(&self) -> String {
60	        let Self { module } = self;
61	        format!("Use `{module}.lowlevel.checkpoint()` instead of `{module}.sleep(0)`")
62	    }
63	
64	    fn fix_title(&self) -> String {
65	        let Self { module } = self;
66	        format!("Replace with `{module}.lowlevel.checkpoint()`")
67	    }
68	}
69	
70	/// ASYNC115
71	pub(crate) fn async_zero_sleep(checker: &Checker, call: &ExprCall) {
72	    if !(checker.semantic().seen_module(Modules::TRIO)
73	        || checker.semantic().seen_module(Modules::ANYIO))
74	    {
75	        return;
76	    }
77	
78	    if call.arguments.len() != 1 {
79	        return;
80	    }
81	
82	    let Some(qualified_name) = checker
83	        .semantic()
84	        .resolve_qualified_name(call.func.as_ref())
85	    else {
86	        return;
87	    };
88	
89	    let Some(module) = AsyncModule::try_from(&qualified_name) else {
90	        return;
91	    };
92	
93	    // Determine the correct argument name
94	    let arg_name = match module {
95	        AsyncModule::Trio => "seconds",
96	        AsyncModule::AnyIo => "delay",
97	        AsyncModule::AsyncIo => return,
98	    };
99	
100	    let Some(arg) = call.arguments.find_argument_value(arg_name, 0) else {
101	        return;
102	    };
103	
104	    match arg {
105	        Expr::NumberLiteral(ast::ExprNumberLiteral { value, .. }) => {
106	            if !matches!(value, Number::Int(Int::ZERO)) {
107	                return;
108	            }
109	        }
110	        _ => return,
111	    }
112	
113	    let Some(qualified_name) = checker
114	        .semantic()
115	        .resolve_qualified_name(call.func.as_ref())
116	    else {
117	        return;
118	    };
119	
120	    if let Some(module) = AsyncModule::try_from(&qualified_name) {
121	        let is_relevant_module = matches!(module, AsyncModule::Trio | AsyncModule::AnyIo);
122	
123	        let is_sleep = is_relevant_module && matches!(qualified_name.segments(), [_, "sleep"]);
124	
125	        if !is_sleep {
126	            return;
127	        }
128	
129	        let mut diagnostic = checker.report_diagnostic(AsyncZeroSleep { module }, call.range());
130	        diagnostic.try_set_fix(|| {
131	            let (import_edit, binding) = checker.importer().get_or_import_symbol(
132	                &ImportRequest::import_from(&module.to_string(), "lowlevel"),
133	                call.func.start(),
134	                checker.semantic(),
135	            )?;
136	            let reference_edit =
137	                Edit::range_replacement(format!("{binding}.checkpoint"), call.func.range());
138	            let arg_edit = Edit::range_replacement("()".to_string(), call.arguments.range());
139	            Ok(Fix::applicable_edits(
140	                import_edit,
141	                [reference_edit, arg_edit],
142	                if checker.comment_ranges().intersects(call.range()) {
143	                    Applicability::Unsafe
144	                } else {
145	                    Applicability::Safe
146	                },
147	            ))
148	        });
149	    }
150	}
